[tikz]% mathsmap-solid {"version":1,"kind":"analytic-cone","radius":2.333,"projectedRadius":0.747,"height":2.567}

\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc,arrows.meta}
% Analytic curved-cone template: ellipse tangencies satisfy sin(theta)=b/H.
\pgfmathsetmacro{\tangentAngle}{asin(0.747/2.567)}
\pgfmathsetmacro{\leftAngle}{180-\tangentAngle}
\pgfmathsetmacro{\frontEndAngle}{360+\tangentAngle}
\pgfmathsetmacro{\tangentX}{2.333*cos(\tangentAngle)}
\pgfmathsetmacro{\tangentY}{0.747*sin(\tangentAngle)}
\coordinate (O) at (0,0);
\coordinate (Ap) at (0,2.567);
\coordinate (Lp) at (-2.333,0);
\coordinate (Rp) at (2.333,0);
\coordinate (Lt) at (-\tangentX,\tangentY);
\coordinate (Rt) at (\tangentX,\tangentY);
% Visible rim and silhouettes meet at the same derived tangent points.
\draw (Lt) arc[start angle=\leftAngle,end angle=\frontEndAngle,x radius=2.333,y radius=0.747];
\draw[dashed] (Rt) arc[start angle=\tangentAngle,end angle=\leftAngle,x radius=2.333,y radius=0.747];
\draw (Lt)--(Ap)--(Rt);
\path (Ap)--(Rt) node[midway,right,xshift=3mm] {$15\text{ cm}$};
% Auxiliary height and radius construction, separate from the silhouette.
\draw[dashed,thin] (Ap)--(O)--(Rp);
\coordinate (ra) at ($(O)!0.28cm!(Ap)$);
\coordinate (rb) at ($(O)!0.28cm!(Rp)$);
\draw[thin] (ra)--($(ra)+(rb)-(O)$)--(rb);
\fill (O) circle (1.2pt);
% External diameter annotation keeps its label clear of the curved rim.
\draw[thin] (Lp)--(-2.333,-1.1);
\draw[thin] (Rp)--(2.333,-1.1);
\draw[{Stealth}-{Stealth}] (-2.333,-1.0)--(2.333,-1.0) node[midway,below] {$20\text{ cm}$};
\end{tikzpicture}
[/tikz]
A cone has base diameter $20\text{ cm}$ and slant height $15\text{ cm}$.
Find its surface area, correct to $1$ decimal place.

